"use client";

/** Implements the reusable board, validation, and result view for 4×4 diagonal Sudoku games. */
import { useMemo, useState } from "react";
import type { SudokuTwistManifest } from "./game-manifest";
import styles from "./sudoku-twist-runtime.module.css";

type Cell = { row: number; column: number };

/**
 * What it does: Creates a mutable board from the immutable puzzle in a manifest.
 * Can be generated by AI?: No.
 */
function createBoard(manifest: SudokuTwistManifest) {
  return manifest.rules.puzzle.map((row) => [...row]);
}

/**
 * What it does: Tests whether a number can legally occupy a cell under normal and diagonal Sudoku rules.
 * Can be generated by AI?: No.
 */
function isValidMove(board: Array<Array<number | null>>, cell: Cell, value: number, manifest: SudokuTwistManifest) {
  const { gridSize, boxSize, twist } = manifest.rules;
  const boardWithoutSelectedCell = board.map((row) => [...row]);
  boardWithoutSelectedCell[cell.row][cell.column] = null;
  const valuesInRow = boardWithoutSelectedCell[cell.row];
  const valuesInColumn = boardWithoutSelectedCell.map((row) => row[cell.column]);
  const boxStartRow = Math.floor(cell.row / boxSize) * boxSize;
  const boxStartColumn = Math.floor(cell.column / boxSize) * boxSize;
  const valuesInBox = Array.from({ length: boxSize * boxSize }, (_, index) => {
    const row = boxStartRow + Math.floor(index / boxSize);
    const column = boxStartColumn + (index % boxSize);
    return boardWithoutSelectedCell[row][column];
  });
  const valuesOnMainDiagonal = boardWithoutSelectedCell.map((row, index) => row[index]);
  const valuesOnReverseDiagonal = boardWithoutSelectedCell.map((row, index) => row[gridSize - 1 - index]);
  const valuesToCheck = [...valuesInRow, ...valuesInColumn, ...valuesInBox];

  if (twist === "both_diagonals_unique" && cell.row === cell.column) valuesToCheck.push(...valuesOnMainDiagonal);
  if (twist === "both_diagonals_unique" && cell.row + cell.column === gridSize - 1) valuesToCheck.push(...valuesOnReverseDiagonal);

  return !valuesToCheck.some((item, index) => item === value && index !== -1);
}

/**
 * What it does: Checks whether every cell has been filled.
 * Can be generated by AI?: No.
 */
function isComplete(board: Array<Array<number | null>>) {
  return board.every((row) => row.every((value) => value !== null));
}

/**
 * What it does: Renders any Sudoku Twist manifest using the permanent shared Sudoku engine.
 * Can be generated by AI?: No.
 */
export function SudokuTwistRuntime({ manifest }: { manifest: SudokuTwistManifest }) {
  const [board, setBoard] = useState(() => createBoard(manifest));
  const [selectedCell, setSelectedCell] = useState<Cell | null>(null);
  const [mistakes, setMistakes] = useState(0);
  const [message, setMessage] = useState("Choose an empty cell, then a number.");
  const fixedCells = useMemo(() => manifest.rules.puzzle.map((row) => row.map((value) => value !== null)), [manifest]);
  const complete = isComplete(board);

  const selectCell = (cell: Cell) => {
    if (complete || fixedCells[cell.row][cell.column]) return;
    setSelectedCell(cell);
    setMessage("Choose a number from 1 to 4.");
  };

  const placeNumber = (value: number) => {
    if (!selectedCell || complete) return;
    if (!isValidMove(board, selectedCell, value, manifest)) {
      setMistakes((count) => count + 1);
      setMessage("That breaks a row, column, box, or diagonal rule.");
      return;
    }

    const nextBoard = board.map((row) => [...row]);
    nextBoard[selectedCell.row][selectedCell.column] = value;
    setBoard(nextBoard);
    setSelectedCell(null);
    setMessage(isComplete(nextBoard) ? "Puzzle solved!" : "Correct move. Choose another cell.");
  };

  const restart = () => {
    setBoard(createBoard(manifest));
    setSelectedCell(null);
    setMistakes(0);
    setMessage("Choose an empty cell, then a number.");
  };

  return (
    <section className={styles.game} style={{ background: manifest.theme.pageBackground, color: manifest.theme.textColor }} aria-label={manifest.metadata.title}>
      <div className={styles.content}>
        <p className={styles.eyebrow}>DIAGONAL SUDOKU</p>
        <h1>{manifest.metadata.title}</h1>
        <p className={styles.instructions}>{manifest.metadata.instructions}</p>
        <p className={styles.message} aria-live="polite">{message}</p>
        <div className={styles.board}>
          {board.flatMap((row, rowIndex) => row.map((value, columnIndex) => {
            const selected = selectedCell?.row === rowIndex && selectedCell?.column === columnIndex;
            const fixed = fixedCells[rowIndex][columnIndex];
            const diagonal = rowIndex === columnIndex || rowIndex + columnIndex === manifest.rules.gridSize - 1;
            return <button key={`${rowIndex}-${columnIndex}`} type="button" className={`${styles.cell} ${selected ? styles.selected : ""} ${fixed ? styles.fixed : ""} ${diagonal ? styles.diagonal : ""}`} disabled={fixed || complete} onClick={() => selectCell({ row: rowIndex, column: columnIndex })}>{value ?? ""}</button>;
          }))}
        </div>
        <div className={styles.keypad} aria-label="Number keypad">
          {[1, 2, 3, 4].map((value) => <button key={value} type="button" onClick={() => placeNumber(value)} style={{ borderColor: manifest.theme.accentColor }}>{value}</button>)}
        </div>
        <div className={styles.footer}><span>Mistakes: {mistakes}</span>{complete && <button type="button" onClick={restart} style={{ background: manifest.theme.accentColor }}>Play again</button>}</div>
      </div>
    </section>
  );
}
